const ENGINE_LAYER_NAME = "_KAIOA_PREVIEW";
let updatePending = false;
let gameProcess = null; // Keep reference to prevent GC killing the game launcher

// --- MATH UTILS STUB ---
// Injected by Bundler

// --- CONFIG SYNC SYSTEM ---

function syncConfigToMap(map) {
    if (!map) return;
    map.macro("Load Game Config", () => {
        const p = KAIOA_CONFIG.lighting.palette;
        setMapProp(map, "kaioa_light_night_color", colorToHex(p.night));
        setMapProp(map, "kaioa_light_dawn_color", colorToHex(p.dawn));
        setMapProp(map, "kaioa_light_day_color", colorToHex(p.day));
        setMapProp(map, "kaioa_light_dusk_color", colorToHex(p.dusk));
        
        setMapProp(map, "kaioa_phys_player_radius", KAIOA_CONFIG.physics.playerRadius);
        setMapProp(map, "kaioa_phys_player_speed", KAIOA_CONFIG.physics.playerSpeed);

        if (typeof map.property("kaioa_time") === 'undefined') {
            map.setProperty("kaioa_time", 12.0);
        }
    });
    tiled.log("[Kaioa] Map Properties synced with Config.");
}

function setMapProp(map, key, value) {
    if (map.property(key) !== value) {
        map.setProperty(key, value);
    }
}

function colorToHex(c) {
    if (!c) return "#ffffff";
    const toHex = (n) => n.toString(16).padStart(2, '0');
    return `#${toHex(c.r)}${toHex(c.g)}${toHex(c.b)}`;
}

function hexToRgb(hex) {
    const clean = hex.replace('#', '');
    const bigint = parseInt(clean, 16);
    return {
        r: (bigint >> 16) & 255,
        g: (bigint >> 8) & 255,
        b: bigint & 255
    };
}

function saveConfigFromMap(map) {
    if (!map) return;
    
    const newConfig = JSON.parse(JSON.stringify(KAIOA_CONFIG)); 
    
    newConfig.physics.playerRadius = map.property("kaioa_phys_player_radius") ?? newConfig.physics.playerRadius;
    newConfig.physics.playerSpeed = map.property("kaioa_phys_player_speed") ?? newConfig.physics.playerSpeed;

    const updateColor = (key, target) => {
        const hex = map.property(key);
        if (hex) {
            const rgb = hexToRgb(hex);
            target.r = rgb.r;
            target.g = rgb.g;
            target.b = rgb.b;
        }
    };

    updateColor("kaioa_light_night_color", newConfig.lighting.palette.night);
    updateColor("kaioa_light_dawn_color", newConfig.lighting.palette.dawn);
    updateColor("kaioa_light_day_color", newConfig.lighting.palette.day);
    updateColor("kaioa_light_dusk_color", newConfig.lighting.palette.dusk);

    const file = new TextFile(KAIOA_PROJECT_CONFIG_PATH, TextFile.WriteOnly);
    file.write(JSON.stringify(newConfig, null, 4));
    file.close(); 
    
    tiled.log(`[Kaioa] Config Saved to ${KAIOA_PROJECT_CONFIG_PATH}`);
}

/**
 * Updates Tiled's native layer visibility based on the selected floor.
 */
function updateMapLayerVisibility(map, viewFloor) {
    for (let i = 0; i < map.layerCount; ++i) {
        const layer = map.layerAt(i);
        const name = layer.name.toLowerCase();
        
        if (name === ENGINE_LAYER_NAME.toLowerCase()) {
            layer.visible = true;
            continue;
        }

        let isFloorSpecific = false;
        let layerFloor = 0;
        
        if (name.includes("_f1") || name.includes("floor1")) { isFloorSpecific = true; layerFloor = 1; }
        else if (name.includes("_f2") || name.includes("floor2")) { isFloorSpecific = true; layerFloor = 2; }
        else if (name.includes("_base") || name.includes("basement")) { isFloorSpecific = true; layerFloor = -1; }
        else if (name.includes("_f0") || name.includes("floor0")) { isFloorSpecific = true; layerFloor = 0; }

        if (isFloorSpecific) {
            layer.visible = (layerFloor === viewFloor);
        } else {
            // Keep shared layers visible only on ground floor for safety
            layer.visible = (viewFloor === 0); 
        }
    }
}

function findLayerByName(map, name) {
    for (let i = 0; i < map.layerCount; ++i) {
        if (map.layerAt(i).name === name) return map.layerAt(i);
    }
    return null;
}

// --- RENDERER ---

function renderScene() {
    const map = tiled.activeAsset;
    if (!map || !map.isTileMap) return;

    // READ LIVE PROPERTIES
    const playerRadius = map.property("kaioa_phys_player_radius") || 12;
    const mapTime = map.property("kaioa_time") || 12.0;
    const viewFloor = map.property("kaioa_view_floor") ?? 0;

    // Update native visibility first
    updateMapLayerVisibility(map, viewFloor);

    // Layer Setup
    let group = findLayerByName(map, ENGINE_LAYER_NAME);
    if (group) map.removeLayer(group);
    
    group = new GroupLayer(ENGINE_LAYER_NAME);
    group.locked = true; 
    map.addLayer(group);

    const shadowLayer = new ObjectGroup("Shadows");
    shadowLayer.opacity = 0.5;
    shadowLayer.color = "#000000";
    group.addLayer(shadowLayer);

    const lightLayer = new ObjectGroup("Light Gizmos");
    lightLayer.opacity = 0.3;
    group.addLayer(lightLayer);

    const physicsLayer = new ObjectGroup("Physics");
    physicsLayer.opacity = 0.7;
    physicsLayer.color = "#00ff00";
    group.addLayer(physicsLayer);

    const rulesLayer = new ObjectGroup("GameRules");
    rulesLayer.opacity = 0.6;
    group.addLayer(rulesLayer);

    // --- RENDER LOGIC ---
    // 1. Lights
    const lightsObjLayer = findLayerByName(map, "Lights");
    const furnitureLayer = findLayerByName(map, "Furniture");
    const entitiesLayer = findLayerByName(map, "Entities") || findLayerByName(map, "NPCs");
    const logicLayer = findLayerByName(map, "Logic");

    // ... (Existing Light Logic) ...

    // --- 5. MECHANICS VISUALIZATION (Game Rules) ---
    if (logicLayer && logicLayer.isObjectLayer) {
        for (const obj of logicLayer.objects) {
            let color = null;
            let label = "";
            let shape = "rect"; // rect or ellipse

            // A. Duel Zones (Red)
            if (obj.type === "duel_zone") {
                color = "#ff0000";
                label = "⚔️ PVP";
                shape = "ellipse";
            }
            // B. Sanctuaries (Blue) - Detect by name (Dorm/Infirmary) or prop
            else if (obj.name && (obj.name.includes("DORM") || obj.name.includes("INFIRMARY"))) {
                color = "#0088ff";
                label = "🛡️ SAFE";
            }
            // C. Exits (Green)
            else if (obj.type === "exit" || obj.name.includes("exit")) {
                color = "#00ff00";
                label = "🚪 EXIT";
            }
            // D. Story Locations (Yellow)
            else if (obj.type === "location") {
                color = "#ffff00";
                label = "📍 " + obj.name;
            }
            // E. Stairs (Cyan)
            else if (obj.type === "stair") {
                color = "#00ffff";
                const target = obj.property("toFloor") ?? 1;
                label = "📶 TO F" + target;
            }
            // F. Item Spawns (Gold)
            else if (obj.type === "item_spawn") {
                color = "#ffd700"; // Gold
                label = "💎 ITEM";
                shape = "ellipse"; // Small circle/diamond
                // Custom shape for diamond? Tiled script API supports Polygon but simpler to use Ellipse for now.
            }

            if (color) {
                // Draw Zone Area
                const zone = new MapObject();
                zone.shape = (shape === "ellipse") ? MapObject.Ellipse : MapObject.Rectangle;
                zone.x = obj.x;
                zone.y = obj.y;
                zone.width = obj.width;
                zone.height = obj.height;
                // zone.fillColor = color + "44"; // 44 = ~25% alpha
                zone.name = label;
                rulesLayer.addObject(zone);

                // Draw Label Centered
                const text = new MapObject();
                text.shape = MapObject.Text;
                text.x = obj.x;
                text.y = obj.y + (obj.height / 2) - 10;
                text.width = obj.width;
                text.height = 20;
                text.text = label;
                text.textColor = color;
                text.halign = 1; // Center
                rulesLayer.addObject(text);
            }
        }
    }

    // --- 6. STATIC PHYSICS (Walls) ---
    // Iterate all layers to find collision layers
    for (let i = 0; i < map.layerCount; i++) {
        const layer = map.layerAt(i);
        if (layer.isObjectLayer && (layer.name.includes("Collision") || layer.name.includes("Col"))) {
            for (const obj of layer.objects) {
                const wall = new MapObject();
                wall.shape = MapObject.Rectangle;
                wall.x = obj.x;
                wall.y = obj.y;
                wall.width = obj.width;
                wall.height = obj.height;
                wall.name = "WALL";
                // Color: Red for blocking
                // Note: In Tiled scripting, we can't easily set fill color on arbitrary objects without type
                // But we put them in 'Physics' group which is Green.
                // Let's rely on the group color, or add to a specific "Walls" group if we want Red.
                physicsLayer.addObject(wall);
            }
        }
    }

    const activeLights = [];

    if (lightsObjLayer && lightsObjLayer.isObjectLayer) {
        for (const light of lightsObjLayer.objects) {
            // Check if light has a 'floor' property
            const lightFloor = light.property("floor") ?? 0;
            if (lightFloor !== viewFloor) continue;

            const radius = light.property("radius") || 200;
            const gizmo = new MapObject();
            gizmo.shape = MapObject.Ellipse;
            gizmo.width = radius * 2;
            gizmo.height = radius * 2;
            gizmo.x = light.x - radius;
            gizmo.y = light.y - radius;
            gizmo.name = "R: " + radius;
            lightLayer.addObject(gizmo);
            activeLights.push({ x: light.x, y: light.y, radius: radius });
        }
    }

    // 2. Sun (Time Scrubber)
    const centerX = map.width * map.tileWidth / 2;
    const centerY = map.height * map.tileHeight / 2;
    const sunPos = KaioaMath.calculateSunPosition(mapTime, centerX, centerY, 2500);
    
    const sunGizmo = new MapObject();
    sunGizmo.shape = MapObject.Ellipse;
    sunGizmo.width = 100;
    sunGizmo.height = 100;
    sunGizmo.x = sunPos.x - 50;
    sunGizmo.y = sunPos.y - 50;
    sunGizmo.name = "SUN (" + mapTime + "h)";
    lightLayer.addObject(sunGizmo);
    activeLights.push({ x: sunPos.x, y: sunPos.y, radius: 10000, isSun: true });

    // 3. Shadows (Unified)
    const renderShadow = (layer) => {
        if (!layer) return;

        // Detect Layer Floor
        let layerFloor = 0;
        const name = layer.name.toLowerCase();
        if (name.includes("_f1") || name.includes("floor1")) layerFloor = 1;
        else if (name.includes("_f2") || name.includes("floor2")) layerFloor = 2;
        else if (name.includes("_base") || name.includes("basement")) layerFloor = -1;

        if (layerFloor !== viewFloor) return; // Skip shadows for other floors

        const tileW = map.tileWidth;
        const tileH = map.tileHeight;
        
        // Handle Tile Layers (Furniture)
        if (layer.isTileLayer) {
            const region = layer.region(); 
            for (const rect of region.rects) {
                for (let y = rect.y; y < rect.y + rect.height; y++) {
                    for (let x = rect.x; x < rect.x + rect.width; x++) {
                        const tile = layer.tileAt(x, y);
                        if (tile) {
                            const worldX = x * tileW;
                            const worldY = y * tileH;
                            castShadowFromRect(worldX, worldY, tileW, tileH, activeLights, shadowLayer);
                        }
                    }
                }
            }
        }
        
        // Handle Object Layers (Entities/NPCs)
        if (layer.isObjectLayer) {
            for (const obj of layer.objects) {
                const w = obj.width || 32;
                const h = obj.height || 32;
                // Object coordinates are usually Bottom-Left for Tile Objects, Top-Left for Rects.
                // Assuming standard Tile Objects (Insert Tile): X,Y is Bottom-Left.
                // If it's a Rect/Ellipse object, X,Y is Top-Left.
                // Tiled API ambiguity: tile objects have 'obj.tile'.
                let baseY = obj.y;
                if (!obj.tile) baseY += h; // If it's a shape, y is top.
                
                // Let's rely on visual checking. If shadows float, we invert logic.
                castShadowFromRect(obj.x, obj.y - h, w, h, activeLights, shadowLayer);
            }
        }
    };

        const castShadowFromRect = (worldX, worldY, w, h, lights, targetLayer) => {

            const cx = worldX + w/2;

            const cy = worldY + h; 

    

            let nearest = null;

            let minDSq = Infinity;

    

            for (const light of lights) {

                const dSq = (light.x - cx)**2 + (light.y - cy)**2;

                const r = light.radius;

                if (light.isSun) {

                    if (!nearest || !nearest.isPoint) {

                        nearest = light;

                        minDSq = dSq; 

                    }

                } else {

                    if (dSq < r*r && dSq < minDSq) {

                        minDSq = dSq;

                        nearest = light;

                        nearest.isPoint = true;

                    }

                }

            }

    

            if (nearest) {

                const polyPoints = KaioaMath.calculateShadowProjection(

                    {x: worldX, y: worldY, width: w, height: h}, 

                    nearest,

                    0.6, // skewX

                    0.25 // skewY

                );

                const shadowObj = new MapObject();

                shadowObj.shape = MapObject.Polygon;

                shadowObj.x = 0; 

                shadowObj.polygon = polyPoints;

                targetLayer.addObject(shadowObj);

            }

        };

    

        // Removed duplicate declarations. Using variables from top of function.

        if (furnitureLayer) renderShadow(furnitureLayer);

        if (entitiesLayer) renderShadow(entitiesLayer);

    

        // 4. Physics (Live Radius) & Spawn Visualization
    const renderSpawns = (layer) => {
        if (!layer || !layer.isObjectLayer) return;
        
        for (const obj of layer.objects) {
            let entityType = null;
            let color = "#aaaaaa";
            let label = "";
            let radius = 12;

            // Detect Spawn Type
            if (obj.name === "Spawn") {
                entityType = "player";
                color = "#00ff00"; // Green for Main Player Spawn
                label = "PLAYER START";
            } else if (obj.name.startsWith("bed_")) {
                entityType = "npc_sleep";
                // Determine House by Zone? Too complex for now.
                color = "#8888ff"; 
                label = "Student (Sleep)";
            } else if (obj.name.startsWith("seat_class")) {
                entityType = "npc_sit";
                color = "#ffff88";
                label = "Student (Class)";
            } else if (obj.type === "teacher" || obj.name.includes("Professor")) {
                entityType = "teacher";
                color = "#ffffff";
                label = "Teacher";
                radius = 14;
            }

            if (entityType) {
                // A. Draw Physics Collider
                // Check if radius override exists in config? Using default for now.
                if (entityType === "player" || entityType.includes("npc")) radius = playerRadius;

                const colliderGizmo = new MapObject();
                colliderGizmo.shape = MapObject.Ellipse;
                colliderGizmo.width = radius * 2;
                colliderGizmo.height = radius * 2;
                colliderGizmo.x = obj.x - radius + (obj.width/2); // Center relative to obj center
                colliderGizmo.y = obj.y - radius + (obj.height/2);
                colliderGizmo.name = "Collider";
                // colliderGizmo.fillColor = "#00ff0044"; // Semi-transparent green
                physicsLayer.addObject(colliderGizmo);

                // B. Draw Visual Proxy (Body)
                const bodyGizmo = new MapObject();
                bodyGizmo.shape = MapObject.Ellipse;
                bodyGizmo.width = 24;
                bodyGizmo.height = 24;
                bodyGizmo.x = obj.x - 12 + (obj.width/2);
                bodyGizmo.y = obj.y - 24 + (obj.height/2); // Offset up for body visuals
                bodyGizmo.name = label;
                // bodyGizmo.fillColor = color;
                // Add Text Label? Tiled MapObject text property
                // bodyGizmo.text = label; // Only for Text objects
                
                // Text Object for Label
                const textObj = new MapObject();
                textObj.shape = MapObject.Text;
                textObj.x = obj.x - 20;
                textObj.y = obj.y - 40;
                textObj.width = 100;
                textObj.height = 20;
                textObj.text = label;
                textObj.textColor = color;
                
                // Add to a "Visuals" layer inside preview?
                // Let's put in lightLayer for now or a new one.
                lightLayer.addObject(bodyGizmo); // Reuse gizmo layer
                lightLayer.addObject(textObj);

                // C. Cast Shadow for this Virtual Entity
                // We use the position of the spawn point as the "entity" position
                // Assuming standard humanoid size 32x64
                castShadowFromRect(obj.x + (obj.width/2) - 16, obj.y + (obj.height/2) - 32, 32, 64, activeLights, shadowLayer);
            }
            
            // Also draw physics for explicit entities defined in Entities layer
            else if (layer.name === "Entities" || layer.name === "NPCs") {
                 const collider = KaioaMath.getEntityCollider(obj.type || obj.name);
                 let r = collider.radius;
                 if (collider.shape === 'circle') {
                    if (r === 12) r = playerRadius; 
                    const gizmo = new MapObject();
                    gizmo.shape = MapObject.Ellipse;
                    gizmo.width = r * 2;
                    gizmo.height = r * 2;
                    gizmo.x = obj.x - r + collider.offsetX;
                    gizmo.y = obj.y - r + collider.offsetY;
                    gizmo.name = "Body";
                    physicsLayer.addObject(gizmo);
                 }
            }
        }
    };

    if (entitiesLayer) renderSpawns(entitiesLayer);
    const seatsLayer = findLayerByName(map, "FixedSeats");
    if (seatsLayer) renderSpawns(seatsLayer);
    const logicLayer = findLayerByName(map, "Logic"); // Where 'Spawn' is usually
    if (logicLayer) renderSpawns(logicLayer);

    updatePending = false;
}

function requestUpdate() {
    if (!updatePending) {
        updatePending = true;
        renderScene();
    }
}

// --- ACTIONS & UI ---

// 1. Auto-Render Toggle
const actionRender = tiled.registerAction("KaioaRenderToggle", function(action) {
    if (action.checked) {
        requestUpdate();
        tiled.log("[Kaioa] Auto-Render ENABLED");
    } else {
        tiled.log("[Kaioa] Auto-Render DISABLED");
    }
});
actionRender.text = "Auto-Render";
actionRender.checkable = true;
actionRender.checked = true; 
actionRender.icon = "visible"; 

// 2. Load Config
const actionLoad = tiled.registerAction("KaioaLoadConfig", function(action) {
    syncConfigToMap(tiled.activeAsset);
});
actionLoad.text = "Reload Config";
actionLoad.icon = "view-refresh"; // Standard Tiled icon

// 3. Play Button
const actionPlay = tiled.registerAction("KaioaPlay", function(action) {
    tiled.log("[Kaioa] Launching Game Environment...");
    
    let projectRoot = "D:/Cliffwald2D"; 
    if (typeof KAIOA_PROJECT_CONFIG_PATH !== 'undefined') {
        const parts = KAIOA_PROJECT_CONFIG_PATH.split('/');
        parts.pop(); parts.pop(); parts.pop();
        projectRoot = parts.join('/');
    }

    const batFile = projectRoot + "/start_mmo.bat";
    
    gameProcess = new Process();
    gameProcess.start("cmd", ["/c", "start", batFile]);
});
actionPlay.text = "Play Game";
actionPlay.shortcut = "F5";
actionPlay.icon = "media-playback-start"; // Standard Tiled icon

// --- FLOOR SWITCHERS ---
const switchFloor = (f) => {
    const map = tiled.activeAsset;
    if (map) {
        map.setProperty("kaioa_view_floor", f);
        requestUpdate();
        tiled.log(`[Kaioa] Switched to Floor ${f}`);
    }
};

const actionNext = tiled.registerAction("KaioaNextFloor", () => {
    const map = tiled.activeAsset;
    if (!map) return;
    const current = map.property("kaioa_view_floor") ?? 0;
    const floors = [-1, 0, 1];
    let idx = floors.indexOf(current);
    let next = floors[(idx + 1) % floors.length];
    switchFloor(next);
});
actionNext.text = "Next Floor (Cycle)";
actionNext.icon = "view-refresh"; // Circular arrow

const actionF0 = tiled.registerAction("KaioaViewF0", () => switchFloor(0));
actionF0.text = "View Ground (F0)";
actionF0.icon = "go-home"; // Building/Home icon

const actionF1 = tiled.registerAction("KaioaViewF1", () => switchFloor(1));
actionF1.text = "View Upper (F1)";
actionF1.icon = "go-up"; 

const actionFBase = tiled.registerAction("KaioaViewBase", () => switchFloor(-1));
actionFBase.text = "View Basement";
actionFBase.icon = "go-down"; 

// Menu Integration
tiled.extendMenu("Map", [
    { separator: true },
    { action: "KaioaPlay" },
    { action: "KaioaRenderToggle" },
    { action: "KaioaLoadConfig" },
    { separator: true },
    { action: "KaioaNextFloor" },
    { action: "KaioaViewF1" },
    { action: "KaioaViewF0" },
    { action: "KaioaViewBase" }
]);

// --- AUTO-HOOK LOGIC ---

function checkAndRequestUpdate() {
    if (actionRender.checked) {
        requestUpdate();
    }
}

tiled.activeAssetChanged.connect(function() {
    const map = tiled.activeAsset;
    if (map && map.isTileMap) {
        if (typeof map.property("kaioa_phys_player_radius") === 'undefined') {
            syncConfigToMap(map);
        }
        checkAndRequestUpdate();
    }
});

tiled.assetSaved.connect(function(asset) {
    if (asset.isTileMap) {
        saveConfigFromMap(asset);
        checkAndRequestUpdate();
    }
});

tiled.log("KaioaEngine Ready. Customize your toolbar to add Play/Render buttons.");

tiled.log("KaioaEngine Booted Successfully.");